-- ResourceManager Module
-- Defines all resource types, rarity, sell price, required level, etc.

local ResourceManager = {}

-- Define resource data
ResourceManager.Resources = {
    -- Common
    ScrapMetal = {
        Rarity = "Common",
        Value = 10,
        Description = "Basic scrap metal",
    },
    Wood = {
        Rarity = "Common",
        Value = 12,
        Description = "Simple wood plank",
    },
    Stone = {
        Rarity = "Common",
        Description = "Rough stone block",
        Value = 15
    },

    -- Uncommon
    AncientTech = {
        Rarity = "Uncommon",
        Value = 50,
        Description = "Ancient technological component",
    },
    CrystalShard = {
        Rarity = "Uncommon",
        Value = 60,
        Description = "Shiny crystal shard",
    },

    -- Rare
    EnergyCore = {
        Rarity = "Rare",
        Value = 200,
        Description = "Pulsing energy core",
    },

    -- Legendary
    SkyRelic = {
        Rarity = "Legendary",
        Value = 1000,
        Description = "Mystic sky relic",
    },
    LostArtifact = {
        Rarity = "Legendary",
        Value = 1200,
        Description = "Ancient lost artifact",
    },
    CelestialFragment = {
        Rarity = "Legendary",
        Value = 1500,
        Description = "Fragment of a celestial body",
    },
}

-- Function to get resource info by name
function ResourceManager.GetResourceInfo(name)
    return ResourceManager.Resources[name]
end

-- Function to get resources by rarity
function ResourceManager.GetResourcesByRarity(rarity)
    local result = {}
    for name, data in pairs(ResourceManager.Resources) do
        if data.Rarity == rarity then
            result[name] = data
        end
    end
    return result
end

return ResourceManager

